body.script:
//
    "use strict";

    const BASE_PATH = location.pathname.replace(/\/[^\/]*$/, "/");
    const swAllowedHostnames = ["localhost", "127.0.0.1"];

    const WISPS = [
      { id: "zaka-cf", name: "Zaka (CloudFront)", url: "wss://d1vajlb5xnngpm.cloudfront.net/api/", group: "Zaka" },
      { id: "mercury", name: "Mercury Workshop", url: "wss://wisp.mercurywork.shop/", group: "Community" },
      { id: "space", name: "Go Into Space", url: "wss://gointospace.app/wisp/", group: "Community" },
      { id: "anura", name: "Anura", url: "wss://anura.pro/", group: "Community" },
      { id: "tomp", name: "TOMP Bare", url: "wss://bare-server.fly.dev/wisp/", group: "Community" },
      { id: "pgis-main", name: "PGIS Main", url: "wss://pgis-wisp.joytree.site/", group: "PGIS" },
      { id: "pgis-1", name: "PGIS Frankfurt", url: "wss://pgis-wisp.onrender.com/", group: "PGIS" },
      { id: "pgis-2", name: "PGIS Ohio", url: "wss://pgis-wisp-2.onrender.com/", group: "PGIS" },
      { id: "pgis-3", name: "PGIS Singapore", url: "wss://pgis-wisp-3.onrender.com/", group: "PGIS" },
      { id: "pgis-4", name: "PGIS Oregon", url: "wss://pgis-wisp-4.onrender.com/", group: "PGIS" },
      { id: "petezah", name: "PeteZah", url: "wss://petezahgames.com/wisp/", group: "PeteZah" },
      { id: "petezah-2", name: "PeteZah 2", url: "wss://3658729.ritebooks.com/wisp/", group: "PeteZah" },
      { id: "petezah-3", name: "PeteZah 3", url: "wss://sciencepark.cc/wisp/", group: "PeteZah" },
      { id: "petezah-4", name: "PeteZah 4", url: "wss://homeworkhelp.cc/wisp/", group: "PeteZah" },
      { id: "bestspark", name: "bestspark.org", url: "wss://bestspark.org/wisp/", group: "Local" },
      { id: "local", name: "Same-origin /wisp/", url: (location.protocol === "https:" ? "wss://" : "ws://") + location.host + "/wisp/", group: "Local" },
      { id: "custom", name: "Custom (enter in Settings)", url: "", group: "Custom" }
    ];

    const wispSelect = document.getElementById("wisp-select");
    const customWisp = document.getElementById("custom-wisp");

    (function fillWispSelect() {
      const groups = [];
      WISPS.forEach((w) => {
        if (!groups.includes(w.group)) groups.push(w.group);
      });
      groups.forEach((g) => {
        const og = document.createElement("optgroup");
        og.label = g;
        WISPS.filter((w) => w.group === g).forEach((w) => {
          const opt = document.createElement("option");
          opt.value = w.id;
          opt.textContent = w.name;
          og.appendChild(opt);
        });
        wispSelect.appendChild(og);
      });
    })();

    const savedId = localStorage.getItem("sj-wisp-id");
    const savedCustom = localStorage.getItem("sj-wisp-custom") || "";
    if (savedId && WISPS.some((w) => w.id === savedId)) wispSelect.value = savedId;
    customWisp.value = savedCustom;
    if (wispSelect.value === "custom") customWisp.style.display = "block";

    wispSelect.addEventListener("change", () => {
      customWisp.style.display = wispSelect.value === "custom" ? "block" : "none";
      localStorage.setItem("sj-wisp-id", wispSelect.value);
      if (wispSelect.value === "custom") customWisp.focus();
    });
    customWisp.addEventListener("change", () => {
      localStorage.setItem("sj-wisp-custom", customWisp.value.trim());
    });

    function probeWisp(url) {
      return new Promise((resolve) => {
        let done = false;
        let ws;
        const finish = (ok) => {
          if (done) return;
          done = true;
          try { ws.close(); } catch (e) {}
          resolve(ok);
        };
        try {
          ws = new WebSocket(url);
        } catch (e) {
          resolve(false);
          return;
        }
        const timer = setTimeout(() => finish(false), 4000);
        ws.onopen = () => { clearTimeout(timer); finish(true); };
        ws.onerror = () => { clearTimeout(timer); finish(false); };
        ws.onclose = () => { clearTimeout(timer); finish(false); };
      });
    }

    async function findWorkingWisp() {
      const status = document.getElementById("wisp-status");
      const candidates = WISPS.filter((w) => w.id !== "custom" && w.url);
      for (let i = 0; i < candidates.length; i++) {
        const w = candidates[i];
        wispSelect.value = w.id;
        if (status) status.textContent = "Trying " + (i + 1) + "/" + candidates.length + " — " + w.name;
        const ok = await probeWisp(w.url);
        const opt = wispSelect.querySelector('option[value="' + w.id + '"]');
        if (opt) opt.textContent = w.name + (ok ? " (up)" : " (down)");
        if (ok) {
          localStorage.setItem("sj-wisp-id", w.id);
          if (status) status.textContent = "Using " + w.name;
          return w.url;
        }
      }
      if (status) status.textContent = "No Wisp connected. Pick Custom or try again.";
      return null;
    }

    function getSelectedWisp() {
      const entry = WISPS.find((w) => w.id === wispSelect.value);
      if (!entry) return null;
      if (entry.id === "custom") {
        const val = customWisp.value.trim();
        if (!val) { alert("Enter a custom Wisp URL."); return null; }
        if (!val.startsWith("ws://") && !val.startsWith("wss://")) {
          alert("Wisp URL must start with ws:// or wss://");
          return null;
        }
        localStorage.setItem("sj-wisp-custom", val);
        localStorage.setItem("sj-wisp-id", "custom");
        return val;
      }
      localStorage.setItem("sj-wisp-id", entry.id);
      return entry.url;
    }

    function search(input, template) {
      try { return new URL(input).toString(); } catch (err) {}
      try {
        const url = new URL("http://" + input);
        if (url.hostname.includes(".")) return url.toString();
      } catch (err) {}
      if (
        input.includes("strongdog") ||
        input.includes("copchurch.org") ||
        input.includes("venustexas.org") ||
        input.includes("strong dog")
      ) {
        alert("You do know I have StrongDog, right...? It's in the 'Other Games, I guess' section.");
        alert("If you do need a working strongdog link for your blocker, email me at bestspark687090@gmail.com or DM me on discord at BestSpark687090.");
      }
      return template.replace("%s", encodeURIComponent(input));
    }

    async function registerSW() {
      if (!navigator.serviceWorker) {
        if (location.protocol !== "https:" && !swAllowedHostnames.includes(location.hostname))
          throw new Error("Service workers cannot be registered without https.");
        throw new Error("Your browser doesn't support service workers.");
      }
      await navigator.serviceWorker.register(BASE_PATH + "sw.js", {
        scope: BASE_PATH,
        updateViaCache: "none",
      });
    }

    const form = document.getElementById("sj-form");
    const address = document.getElementById("sj-address");
    const searchEngine = document.getElementById("sj-search-engine");
    const frameWrapper = document.getElementById("sj-frame-wrapper");
    const frameElement = document.getElementById("sj-frame");
    const error = document.getElementById("sj-error");
    const errorCode = document.getElementById("sj-error-code");
    const username = document.getElementById("username");

    document.querySelectorAll("*").forEach(function (e) {
      e.addEventListener("keydown", function (ev) {
        if (ev.ctrlKey && ev.shiftKey && ev.code == "KeyZ") {
          if (frameWrapper) frameWrapper.style.display = "none";
        }
      });
    });

    function showErrorScreen(msg, details) {
      frameWrapper.style.display = "none";
      error.textContent = msg;
      errorCode.textContent = details || "";
    }

    let controller = null;
    let frame = null;

    async function initController(forcedUrl) {
      controller = null;
      frame = null;

      const wispUrl = forcedUrl || getSelectedWisp();
      if (!wispUrl) throw new Error("No Wisp server selected");

      const { Controller, config } = window.$scramjetController;

      config.scramjetPath = location.origin + BASE_PATH + "scj/scj.js";
      config.wasmPath = location.origin + BASE_PATH + "scj/scj.wasm";
      config.injectPath = location.origin + BASE_PATH + "controller/controller.inject.js";
      config.prefix = BASE_PATH + "~sj/";

      const transport = new window.LibcurlTransport.LibcurlClient({
        wisp: wispUrl,
      });

      controller = new Controller({
        serviceworker: navigator.serviceWorker.controller,
        transport,
      });
      await controller.wait();

      frame = controller.createFrame(frameElement);
      if (!frame) throw new Error("createFrame returned null — is the iframe element in the DOM?");
    }

    async function navigate(url) {
      if (!url.startsWith("http")) url = "https://" + url;
      const chosen = WISPS.find((w) => w.id === wispSelect.value);
      let wispUrl = null;
      if (chosen && chosen.id === "custom") {
        wispUrl = getSelectedWisp();
      } else if (chosen && chosen.url) {
        const status = document.getElementById("wisp-status");
        if (status) status.textContent = "Checking " + chosen.name + "...";
        const ok = await probeWisp(chosen.url);
        wispUrl = ok ? chosen.url : await findWorkingWisp();
      } else {
        wispUrl = await findWorkingWisp();
      }
      if (!wispUrl) throw new Error("No working Wisp server");
      await initController(wispUrl);
      await frame.go(url);
      frameWrapper.style.display = "flex";
    }

    function newTab() {
      if (username.value == "") { alert("Must enter a username, sorry!"); return; }
      if (address.value == "") { alert("Please type your search/URL into the space below the username field."); return; }
      const url = search(address.value, searchEngine.value);
      window.open(url, "_blank");
    }
    window.newTab = newTab;

    form.addEventListener("submit", async (event) => {
      event.preventDefault();

      if (username.value == "") { alert("Must enter a username, sorry!"); return; }
      if (address.value == "") { alert("Please type your search/URL into the space below the username field."); return; }

      const url = search(address.value, searchEngine.value);

      try {
        await registerSW();
      } catch (err) {
        error.textContent = "Failed to register service worker.";
        errorCode.textContent = err.toString();
        throw err;
      }

      if (!navigator.serviceWorker.controller) {
        await new Promise((resolve) =>
          navigator.serviceWorker.addEventListener("controllerchange", resolve, { once: true })
        );
      }

      try {
        await navigate(url);
      } catch (err) {
        showErrorScreen(err.message, err.stack);
      }
    });

    const goto = new URL(location.href).searchParams.get("goto");
    if (goto) {
      history.replaceState(null, "", location.pathname);
      address.value = goto;
      registerSW()
        .then(() => {
          if (!navigator.serviceWorker.controller) {
            return new Promise((resolve) =>
              navigator.serviceWorker.addEventListener("controllerchange", resolve, { once: true })
            );
          }
        })
        .then(() => navigate(goto))
        .catch((err) => showErrorScreen(err.message, err.stack));
    }

    findWorkingWisp();
  //

svg.script:
//
var fo = document.getElementById("fo");
function r() {
  fo.setAttribute("width", window.innerWidth);
  fo.setAttribute("height", window.innerHeight);
}
r();
window.addEventListener("resize", r);
//
